import{_ as i,o as r,c as s,a2 as a}from"./chunks/framework.Dkj3JE0_.js";const m=JSON.parse('{"title":"Plan allemand des affaires","description":"","frontmatter":{"title":"Plan allemand des affaires"},"headers":[],"relativePath":"fr/blogs/German/plan.md","filePath":"fr/blogs/German/plan.md"}'),t={name:"fr/blogs/German/plan.md"};function n(o,e,l,u,d,c){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="plan-d-apprentissage-de-l-allemand-des-affaires" tabindex="-1">Plan d’apprentissage de l’allemand des affaires <a class="header-anchor" href="#plan-d-apprentissage-de-l-allemand-des-affaires" aria-label="Permalink to &quot;Plan d’apprentissage de l’allemand des affaires&quot;">​</a></h1><blockquote><p><strong>Hypothèse de travail :</strong> un objectif pratique, sans examen, avec environ <strong>4 heures par semaine</strong>. Le premier cycle dure 24 semaines et privilégie les situations professionnelles récurrentes plutôt qu’une couverture large du manuel.</p></blockquote><h2 id="criteres-d-achevement" tabindex="-1">Critères d’achèvement <a class="header-anchor" href="#criteres-d-achevement" aria-label="Permalink to &quot;Critères d’achèvement&quot;">​</a></h2><p>À la fin du cycle, pouvoir sans difficulté :</p><ul><li>présenter son rôle, son parcours, ses projets et ses priorités du moment ;</li><li>participer à une réunion de 30 minutes, demander des précisions et résumer les décisions ;</li><li>écrire un e-mail clair, une relance, un point d’avancement et un désaccord poli ;</li><li>faire une présentation de 5 à 7 minutes et répondre aux questions prévisibles ;</li><li>mener une courte conversation de réseautage ou d’entretien sans repasser à l’anglais.</li></ul><h2 id="rythme-hebdomadaire" tabindex="-1">Rythme hebdomadaire <a class="header-anchor" href="#rythme-hebdomadaire" aria-label="Permalink to &quot;Rythme hebdomadaire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Séance</th><th style="text-align:right;">Durée</th><th>Travail</th></tr></thead><tbody><tr><td>2 séances d’entrée</td><td style="text-align:right;">35 min chacune</td><td>Lire ou écouter de l’allemand professionnel ; relever des expressions utiles, pas des mots isolés.</td></tr><tr><td>2 séances de production</td><td style="text-align:right;">35 min chacune</td><td>Écrire un e-mail ou un point d’avancement et enregistrer une réponse orale.</td></tr><tr><td>1 conversation</td><td style="text-align:right;">45–60 min</td><td>Jouer le scénario professionnel du mois, avec correction.</td></tr><tr><td>1 révision</td><td style="text-align:right;">25 min</td><td>Réutiliser les expressions corrigées et mettre à jour le journal d’erreurs.</td></tr></tbody></table><p>Construire une <strong>banque d’expressions par fonction</strong> : ouvrir, clarifier, approuver, contester, proposer, différer, résumer et conclure.</p><h2 id="feuille-de-route-sur-24-semaines" tabindex="-1">Feuille de route sur 24 semaines <a class="header-anchor" href="#feuille-de-route-sur-24-semaines" aria-label="Permalink to &quot;Feuille de route sur 24 semaines&quot;">​</a></h2><h3 id="mois-1-—-identite-professionnelle" tabindex="-1">Mois 1 — Identité professionnelle <a class="header-anchor" href="#mois-1-—-identite-professionnelle" aria-label="Permalink to &quot;Mois 1 — Identité professionnelle&quot;">​</a></h3><ul><li>Présentations, responsabilités, organisation de l’équipe et parcours professionnel.</li><li>Production clé : une présentation naturelle de 90 secondes et un profil professionnel écrit.</li><li>Remise à niveau grammaticale : ordre des mots, cas après les prépositions courantes et récit au passé.</li></ul><h3 id="mois-2-—-e-mails-et-messages" tabindex="-1">Mois 2 — E-mails et messages <a class="header-anchor" href="#mois-2-—-e-mails-et-messages" aria-label="Permalink to &quot;Mois 2 — E-mails et messages&quot;">​</a></h3><ul><li>Demandes, planification, relances, pièces jointes, échéances et ton.</li><li>Production clé : cinq modèles d’e-mail réutilisables, chacun adapté à une situation réelle.</li><li>Privilégier des phrases concises et des formes modales polies plutôt qu’une formalité ampoulée.</li></ul><h3 id="mois-3-—-reunions" tabindex="-1">Mois 3 — Réunions <a class="header-anchor" href="#mois-3-—-reunions" aria-label="Permalink to &quot;Mois 3 — Réunions&quot;">​</a></h3><ul><li>Langage de l’ordre du jour, prise de parole, clarification, opinion, désaccord et décisions.</li><li>Production clé : animer une réunion simulée de 15 minutes et envoyer le compte rendu ensuite.</li><li>Repérer les positions et les actions à mener, puis reformuler au lieu de traduire.</li></ul><h3 id="mois-4-—-projets-et-resolution-de-problemes" tabindex="-1">Mois 4 — Projets et résolution de problèmes <a class="header-anchor" href="#mois-4-—-projets-et-resolution-de-problemes" aria-label="Permalink to &quot;Mois 4 — Projets et résolution de problèmes&quot;">​</a></h3><ul><li>Avancement, dépendances, risques, retards, arbitrages, données et recommandations.</li><li>Production clé : un point projet hebdomadaire de deux minutes avec un risque et une demande.</li><li>S’entraîner à expliquer graphiques et chiffres sans rédiger chaque phrase à l’avance.</li></ul><h3 id="mois-5-—-presentations-et-persuasion" tabindex="-1">Mois 5 — Présentations et persuasion <a class="header-anchor" href="#mois-5-—-presentations-et-persuasion" aria-label="Permalink to &quot;Mois 5 — Présentations et persuasion&quot;">​</a></h3><ul><li>Annonces de plan, comparaison, mise en relief, preuves, questions et objections.</li><li>Production clé : une présentation enregistrée de 5 à 7 minutes sur un projet du portfolio.</li><li>La refaire après retours jusqu’à ce que l’élocution soit stable, sans l’apprendre par cœur.</li></ul><h3 id="mois-6-—-integration" tabindex="-1">Mois 6 — Intégration <a class="header-anchor" href="#mois-6-—-integration" aria-label="Permalink to &quot;Mois 6 — Intégration&quot;">​</a></h3><ul><li>Réseautage, entretiens, négociation et situations professionnelles interculturelles.</li><li>Production clé : une simulation de 30 minutes qui passe de la conversation informelle à une discussion de projet, puis à un e-mail de suivi.</li><li>Définir le cycle suivant à partir des blocages réels, pas d’une liste générique de niveaux.</li></ul><h2 id="boucle-de-retour-mensuelle" tabindex="-1">Boucle de retour mensuelle <a class="header-anchor" href="#boucle-de-retour-mensuelle" aria-label="Permalink to &quot;Boucle de retour mensuelle&quot;">​</a></h2><p>À la fin de chaque mois, conserver quatre traces :</p><ol><li>un e-mail corrigé ;</li><li>une tâche orale enregistrée ;</li><li>une liste de cinq erreurs récurrentes ;</li><li>dix expressions à forte valeur réutilisées dans plusieurs situations.</li></ol><p>Mesurer la <strong>réussite de la communication</strong>, pas seulement la correction : l’interlocuteur a-t-il compris la demande, la décision, le risque et la prochaine action ?</p><h2 id="les-sept-premiers-jours" tabindex="-1">Les sept premiers jours <a class="header-anchor" href="#les-sept-premiers-jours" aria-label="Permalink to &quot;Les sept premiers jours&quot;">​</a></h2><ul><li>[ ] Enregistrer une présentation professionnelle de deux minutes sans notes.</li><li>[ ] Écrire un e-mail de travail réaliste et le faire corriger.</li><li>[ ] Créer la banque d’expressions par fonction et le journal d’erreurs.</li><li>[ ] Réserver un créneau hebdomadaire de conversation ou de tutorat.</li><li>[ ] Choisir un projet réel comme sujet du portfolio oral sur six mois.</li></ul>',27)])])}const h=i(t,[["render",n]]);export{m as __pageData,h as default};
